defmodule HighWire.Chess.Fold do
  @moduledoc """
  Fold a chess game's play log into a replayable position + history.

  Chess needs no chain and no reveals — there is nothing hidden to commit
  to — so the fold's whole job is order and legality:

  * entries fold by `ply`, counting up from 1; a gap or a repeat stops the
    fold rather than silently reordering the game,
  * the author of a `move` must be the player whose turn it is, so one side
    cannot play both sides of the board,
  * the move must be generated by the position (`Engine.legal/1`), which is
    what refuses a knight hopping through a bishop, a pinned piece moving
    off the pin, and a king stepping into check,
  * a `resign` ends the game for the author's opponent, and only the player
    to move can resign.

  The fold yields the live position, whose turn is next, the phase, the
  engine's verdict (`:playing`, checkmate, stalemate or a draw), the winner
  when there is one, and the move history with the notation each move was
  written in — computed here rather than stored, so a reader sees the same
  move list the players saw.

  A malformed entry stops the fold early; `error` carries the reason
  (`:none` when it succeeds).
  """

  alias HighWire.Chess.Engine

  @type entry :: %{optional(String.t()) => term()}

  @type history_item :: %{
          ply: pos_integer(),
          player: String.t(),
          type: String.t(),
          uci: String.t() | nil,
          san: String.t() | nil,
          note: String.t() | nil
        }

  @type phase :: :opening | :playing | :finished

  @type winner :: %{player: String.t(), reason: atom()} | nil

  @type fold_result :: %{
          position: Engine.t(),
          board: map(),
          turn: Engine.color(),
          check?: boolean(),
          mover: String.t() | nil,
          turn_count: non_neg_integer(),
          phase: phase(),
          white: String.t() | nil,
          black: String.t() | nil,
          winner: winner(),
          verdict: :playing | {:checkmate, Engine.color()} | :stalemate | {:draw, atom()} | nil,
          last_note: String.t() | nil,
          history: [history_item()],
          error: String.t() | :none
        }

  @doc """
  Fold one game. `game` carries `challenger`, `accepter`, `game_id` and
  `challenger_color` (`"white"` when the challenger took white).

  `opts`:

    * `:entries` — `%{player => [entry]}` of already-normalised entries (see
      `HighWire.Chess.Reader`); the default is empty, which folds to the
      opening position.
  """
  @spec fold_game(map(), map()) :: fold_result()
  def fold_game(game, opts \\ %{}) do
    challenger = Map.get(game, :challenger)
    accepter = Map.get(game, :accepter)

    challenger_color = Engine.color(Map.get(game, :challenger_color) || "white") || :white

    {white, black} =
      if challenger_color == :white, do: {challenger, accepter}, else: {accepter, challenger}

    players = %{white: white, black: black}

    entries =
      (Map.get(opts, :entries) || %{})
      |> Enum.flat_map(fn {_player, list} -> list end)
      |> Enum.sort_by(fn entry -> Map.get(entry, "ply") || 0 end)

    folded =
      Enum.reduce_while(
        entries,
        %{pos: Engine.initial(), history: [], last_note: nil, error: :none},
        fn
          _entry, %{error: error} = acc when error != :none ->
            {:cont, acc}

          entry, acc ->
            case step(acc, entry, players) do
              {:ok, acc} -> {:cont, acc}
              {:error, reason} -> {:halt, %{acc | error: reason}}
            end
        end
      )

    finish(folded, players, accepter)
  end

  defp step(acc, entry, players) do
    expected = length(acc.history) + 1
    pos = acc.pos
    mover = players[pos.turn]

    cond do
      Map.get(entry, "ply") != expected ->
        {:error, "ply #{inspect(Map.get(entry, "ply"))} arrived where #{expected} was due"}

      mover == nil ->
        {:error, "nobody is sitting on the #{pos.turn} side"}

      Map.get(entry, "player") != mover ->
        {:error, "#{short(Map.get(entry, "player"))} moved out of turn at ply #{expected}"}

      Map.get(entry, "type") == "resign" ->
        {:ok,
         %{acc | history: acc.history ++ [item(entry, expected, nil)], last_note: entry["note"]}}

      true ->
        uci = Map.get(entry, "uci")

        # One pass: the position is asked once for the move, and answers
        # with the position after it and its notation.
        case Engine.play(pos, uci) do
          {:ok, next, san} ->
            {:ok,
             %{
               acc
               | pos: next,
                 history: acc.history ++ [item(entry, expected, san)],
                 last_note: entry["note"]
             }}

          {:error, :illegal} ->
            {:error, "ply #{expected}: #{uci} is not a legal move"}

          {:error, reason} ->
            {:error, "ply #{expected}: #{inspect(reason)}"}
        end
    end
  end

  defp item(entry, ply, san) do
    %{
      ply: ply,
      player: Map.get(entry, "player"),
      type: Map.get(entry, "type"),
      uci: Map.get(entry, "uci"),
      san: san,
      note: Map.get(entry, "note")
    }
  end

  defp finish(folded, players, accepter) do
    pos = folded.pos
    verdict = Engine.status(pos)
    resigned = List.last(folded.history) |> then(&(&1 && &1.type == "resign" && &1))

    {phase, winner, mover} =
      cond do
        folded.error != :none ->
          {:finished, nil, nil}

        resigned ->
          {:finished, %{player: other_player(players, resigned.player), reason: :resign}, nil}

        match?({:checkmate, _}, verdict) ->
          {:finished, %{player: players[verdict_color(verdict)], reason: :checkmate}, nil}

        verdict == :stalemate ->
          {:finished, nil, nil}

        match?({:draw, _}, verdict) ->
          {:finished, nil, nil}

        accepter == nil ->
          {:opening, nil, players.white}

        true ->
          {:playing, nil, players[pos.turn]}
      end

    %{
      # The whole position travels with the snapshot: the page that plays a
      # move asks the same engine the fold used.
      position: pos,
      board: pos.board,
      turn: pos.turn,
      check?: Engine.in_check?(pos),
      mover: mover,
      turn_count: length(folded.history),
      phase: phase,
      white: players.white,
      black: players.black,
      winner: winner,
      verdict: if(accepter == nil, do: nil, else: verdict),
      last_note: folded.last_note,
      history: folded.history,
      error: folded.error
    }
  end

  defp verdict_color({:checkmate, color}), do: color

  defp other_player(players, id) do
    if players.white == id, do: players.black, else: players.white
  end

  defp short(nil), do: "someone"
  defp short(id) when is_binary(id), do: String.slice(id, 0, 12) <> "…"
end
